"python -c \"\nfrom PIL import Image\n\norig_path = r'C:\\Users\\rayan\\.gemini\\antigravity-ide\\brain\\67baf5e0-fa12-4d71-b463-61366cb729a0\\sorenelle_hero_mockup_1791005711889.jpg'\norig = Image.open(orig_path).convert('RGB')\nCROP_BOX = (150, 100, 600, 780)\ncrop = orig.crop(CROP_BOX)\nANGLE = -4.95\nr_neg = crop.rotate(ANGLE, resample=Image.BICUBIC, expand=False)\n\n# Let's find rows with text: text pixels have r < 100, paper has r > 230\nfor y in range(250, 620, 5):\n    dark_pixels = [x for x in range(50, 440) if r_neg.getpixel((x, y))[0] < 120]\n    if dark_pixels:\n        print(f'y={y}: {len(dark_pixels)} dark pixels (min_x={min(dark_pixels)}, max_x={max(dark_pixels)})')\n    else:\n        print(f'y={y}: blank paper')\n\""